const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/bim_property_files/%7Bid%7D/properties',
  qs: {
    project_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[object_id]': 'SOME_ARRAY_VALUE',
    'filters[category]': 'SOME_ARRAY_VALUE',
    'filters[name]': 'SOME_ARRAY_VALUE',
    'filters[value]': 'SOME_ARRAY_VALUE',
    'filters[query]': 'SOME_STRING_VALUE',
    'filters[curated_list]': 'SOME_BOOLEAN_VALUE',
    'filters[has_uom]': 'SOME_BOOLEAN_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/bim_property_files/%7Bid%7D/properties?project_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bobject_id%5D=SOME_ARRAY_VALUE&filters%5Bcategory%5D=SOME_ARRAY_VALUE&filters%5Bname%5D=SOME_ARRAY_VALUE&filters%5Bvalue%5D=SOME_ARRAY_VALUE&filters%5Bquery%5D=SOME_STRING_VALUE&filters%5Bcurated_list%5D=SOME_BOOLEAN_VALUE&filters%5Bhas_uom%5D=SOME_BOOLEAN_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
